function openJournal(chunks) {
  const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

  let iterator;
  let chunk = null;
  let offset = 0;
  let line = 1;
  let closed = false;
  let eof = false;
  let cleanupPromise;

  function done() {
    return { done: true, value: undefined };
  }

  function event(text, lineNumber) {
    try {
      return {
        done: false,
        value: { line: lineNumber, ok: true, value: JSON.parse(text) }
      };
    } catch {
      return {
        done: false,
        value: { line: lineNumber, ok: false, text }
      };
    }
  }

  function releaseIterator() {
    if (cleanupPromise === undefined) {
      const source = iterator;
      cleanupPromise = Promise.resolve().then(async () => {
        const returnMethod = source.return;
        if (typeof returnMethod === "function") {
          await returnMethod.call(source);
        }
      });
    }
    return cleanupPromise;
  }

  async function close() {
    closed = true;
    chunk = null;
    offset = 0;

    if (iterator !== undefined && !eof) {
      await releaseIterator();
    }
  }

  async function next() {
    if (closed) return done();

    const parts = [];

    try {
      if (iterator === undefined) {
        iterator = chunks[Symbol.asyncIterator]();
        if (closed) {
          await releaseIterator();
          return done();
        }
      }

      for (;;) {
        if (chunk === null) {
          const result = await iterator.next();
          if (closed) return done();

          if (result.done) {
            eof = true;
            closed = true;

            const tail = decoder.decode();
            if (tail.length > 0) parts.push(tail);

            const text = parts.join("");
            return text.trim() === "" ? done() : event(text, line++);
          }

          chunk = result.value;
          offset = 0;

          if (chunk.length === 0) {
            chunk = null;
            continue;
          }
        }

        const newline = chunk.indexOf(10, offset);

        if (newline === -1) {
          const text = decoder.decode(chunk.subarray(offset), {
            stream: true
          });
          if (text.length > 0) parts.push(text);

          chunk = null;
          offset = 0;
          continue;
        }

        const lastPart = decoder.decode(chunk.subarray(offset, newline));
        if (lastPart.length > 0) parts.push(lastPart);

        offset = newline + 1;
        if (offset === chunk.length) {
          chunk = null;
          offset = 0;
        }

        let text = parts.join("");
        parts.length = 0;

        if (text.endsWith("\r")) {
          text = text.slice(0, -1);
        }

        const lineNumber = line++;
        if (text.trim() === "") continue;

        return event(text, lineNumber);
      }
    } catch (error) {
      closed = true;
      chunk = null;
      offset = 0;

      if (iterator !== undefined && !eof) {
        try {
          await releaseIterator();
        } catch {
          // Preserve the original read error.
        }
      }

      throw error;
    }
  }

  return { next, close };
}
